  `AATT_TYPE_ID` varchar(3) NOT NULL COMMENT 'Type of attachment being attached.\nReferences T_MST_ATT_TYPE',
  `AATT_NAME` varchar(256) NOT NULL COMMENT 'Name of this particular document as provided by uploader.',
  `AATT_LOC_TYPE` char(1) NOT NULL COMMENT 'Location type for this attachment\n‘F’ – File (default)\n‘D’ – Database Blob\n',
  `AATT_LOC` varchar(1024) DEFAULT NULL COMMENT 'Relative path name to the Location of the attachment. To reference from SYS_PARAM table',
  `AATT_STORE` mediumblob COMMENT 'The actual attachment in MEDIUMBLOB',
  `AATT_STATUS` char(1) NOT NULL,
  `AATT_VALID_FROM_DT` datetime NOT NULL COMMENT 'Date that this document is valid from',
  `AATT_VALID_TO_DT` datetime NOT NULL DEFAULT '2999-01-01 00:00:00' COMMENT 'Date that this document is valid To',
  `AATT_CREATE_UID` varchar(35) NOT NULL COMMENT 'User who created this signature record',
  `AATT_CREATE_DT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Datetime when record is created',
  `AATT_LUPD_UID` varchar(35) DEFAULT NULL COMMENT 'User who updated this record',
  `AATT_LUPD_DT` datetime DEFAULT NULL COMMENT 'Datetime when record is updated',
  PRIMARY KEY (`AATT_DOC_ID`),
  KEY `FK_AATT_ACCNID_idx` (`AATT_ACCNID`),
  KEY `FK_AATT_TYPE_ID_idx` (`AATT_TYPE_ID`),
  CONSTRAINT `FK_AATT_ACCNID` FOREIGN KEY (`AATT_ACCNID`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_AATT_TYPE_ID` FOREIGN KEY (`AATT_TYPE_ID`) REFERENCES `T_MST_ATT_TYPE` (`MATT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

