  KEY `IDX_T_CORE_ACCN_BILL_4` (`ABNK_BANK_BR`),
  CONSTRAINT `FKY__T_CORE_ACCN_BANK__ABNK_ACCNID` FOREIGN KEY (`ABNK_ACCNID`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FKY__T_CORE_ACCN_BANK__ABNK_BANK` FOREIGN KEY (`ABNK_BANK`) REFERENCES `T_MST_BANK` (`BANK_ID`),
  CONSTRAINT `FKY__T_CORE_ACCN_BANK__ABNK_BANK_BR` FOREIGN KEY (`ABNK_BANK_BR`) REFERENCES `T_MST_BANK_BR` (`BBRA_ID`),
