  `ACCNR_APL_TEL` varchar(1024) NOT NULL,
  `ACCNR_AATT_DOC_TYPE` varchar(35) DEFAULT NULL,
  `ACCNR_AATT_TYPE_ID` varchar(3) DEFAULT NULL,
  `ACCNR_AATT_NAME` varchar(256) DEFAULT NULL,
  `ACCNR_STORE` mediumblob,
  `ACCNR_STATUS` char(1) NOT NULL,
  `ACCNR_CREATE_UID` varchar(35) NOT NULL,
  `ACCNR_CREATE_DT` datetime NOT NULL,
  `ACCNR_LUPD_UID` varchar(35) NOT NULL,
  `ACCNR_LUPD_DT` datetime NOT NULL,
  PRIMARY KEY (`ACCNR_ID`),
  KEY `FK_ACCNR_ACCN_TYPE_idx` (`ACCNR_ACCN_TYPE`),
  KEY `FK_ACCNR_CTYCODE_idx` (`ACCNR_CTYCODE`),
  KEY `FK_ACCNR_AATT_TYPE_ID_idx` (`ACCNR_AATT_TYPE_ID`),
  CONSTRAINT `FK_ACCNR_AATT_TYPE_ID` FOREIGN KEY (`ACCNR_AATT_TYPE_ID`) REFERENCES `T_MST_ATT_TYPE` (`MATT_ID`),
  CONSTRAINT `FK_ACCNR_ACCN_TYPE` FOREIGN KEY (`ACCNR_ACCN_TYPE`) REFERENCES `T_MST_ACCN_TYPE` (`ATYP_ID`),
  CONSTRAINT `FK_ACCNR_CTYCODE` FOREIGN KEY (`ACCNR_CTYCODE`) REFERENCES `T_MST_COUNTRY` (`CTY_CODE`)
