--
-- Table structure for table `T_CORE_ACCN_SIGN`
--

DROP TABLE IF EXISTS `T_CORE_ACCN_SIGN`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_ACCN_SIGN` (
  `ASIG_ID` varchar(35) NOT NULL,
  `ASIG_ACCNID` varchar(35) NOT NULL,
  `ASIG_UID` varchar(35) NOT NULL COMMENT 'Reference to parent account',
  `ASIG_TYPE_ID` varchar(35) NOT NULL COMMENT 'Type of Signatory authorized for this account.',
  `ASIG_STATUS` char(1) NOT NULL COMMENT 'Status of this signature',
  `ASIG_NAME_FIRST` varchar(128) DEFAULT NULL COMMENT 'First Name of Signatory',
  `ASIG_NAME_LAST` varchar(128) DEFAULT NULL COMMENT 'Last Name of Signatory',
  `ASIG_NID` varchar(35) DEFAULT NULL COMMENT 'National ID number that is a unique identifier for this signatory.',
  `ASIG_DESIGNATION` varchar(128) DEFAULT NULL,
  `ASIG_START_DT` datetime DEFAULT NULL,
  `ASIG_END_DT` datetime DEFAULT NULL,
  `ASIG_SIGNATURE_LOC_TYPE` char(1) NOT NULL COMMENT '‘F’ – File (Default)\n‘D’ – Datebase Blob',
  `ASIG_SIGNATURE_LOC` varchar(1024) DEFAULT NULL COMMENT 'Relative path name of the loation of the signature file. To reference from SYS_PARAM table',
  `ASIG_TYPE` varchar(5) DEFAULT NULL,
  `ASIG_NAME` varchar(255) DEFAULT NULL,
  `ASIG_SIGNATURE` mediumblob COMMENT 'Signature in BLOB',
  `ASIG_CREATE_UID` varchar(35) DEFAULT NULL,
  `ASIG_CREATE_DT` datetime DEFAULT NULL,
  `ASIG_LUPD_UID` varchar(35) DEFAULT NULL,
  `ASIG_LUPD_DT` datetime DEFAULT NULL,
  PRIMARY KEY (`ASIG_ID`),
  KEY `ASIG_ACCNID` (`ASIG_ACCNID`,`ASIG_TYPE_ID`,`ASIG_STATUS`),
  KEY `FK_T_CORE_USR_idx` (`ASIG_UID`),
  KEY `FK_T_MST_SIGN_TYPE_idx` (`ASIG_TYPE_ID`),
  CONSTRAINT `FK_T_CORE_ACCN` FOREIGN KEY (`ASIG_ACCNID`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_T_CORE_USR` FOREIGN KEY (`ASIG_UID`) REFERENCES `T_CORE_USR` (`USR_UID`),
  CONSTRAINT `FK_T_MST_SIGN_TYPE` FOREIGN KEY (`ASIG_TYPE_ID`) REFERENCES `T_MST_SIGN_TYPE` (`MSIG_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table store data of an account’s authorized signatories. An account can have multiple signatories for different purposes, which shall be indicated as types of signatory. A signatory need not be an active user in the system. ';
