--
-- Table structure for table `T_CORE_ACCN_SYS`
--

DROP TABLE IF EXISTS `T_CORE_ACCN_SYS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_ACCN_SYS` (
  `ASYS_ACCNID` varchar(35) NOT NULL,
  `ASYS_EP_ID` varchar(35) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'The unique identifier for a particular End-point ID for this account.',
  `ASYS_EP_TYPE` varchar(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'WS' COMMENT 'Type of EndPoint - ''WS'' for web service; ''FT'''' for FTP',
  `ASYS_TYPE` varchar(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'This should contain ''I'' for source systems connecting to CamelOne platform for inbound messages and ''O'' for target systems that CamelOne platform is connecting for ourbound messages.',
  `ASYS_URI_PART_1` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'For ASYS_TYPE of ''O'' this should be used to contain the unique locator of the endpoint - domain or IP address - eg. ''https://110.92.122.18/.\nFor ASYS_TYPE of ''I'' this should be used to store the allowable starting IP address of the system connecting to CamelOne\n',
  `ASYS_URI_PART_2` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT 'For ASYS_TYPE of ''O'' this should contain the second part of the URI, eg. getsomething=xxxx?\nFor ASYS_TYPE of ''I'' this should contain the allowable end IP address of the system connecting to CamelOne',
  `ASYS_URI_PART_3` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `ASYS_USER` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
