CREATE TABLE `T_CORE_GRANT_ROLE_EX` (
  `GNTRLEX_APPS_CODE` varchar(35) NOT NULL COMMENT 'References T_CORE_APPS',
  `GNTRLEX_ROLE_ID` varchar(35) NOT NULL COMMENT 'References T_CORE_ROLE',
  `GNTRLEX_PERM_ID` varchar(35) NOT NULL COMMENT 'References T_CORE_PERM_EX',
  `GNTRLEX_STATUS` char(1) NOT NULL COMMENT 'A is active,I is inactive,Default is A',
  `GNTRLEX_DT_CREATE` datetime NOT NULL COMMENT 'Contains the date where this record is created. Default to CURR_DATE',
  `GNTRLEX_UID_CREATE` varchar(35) NOT NULL COMMENT 'Contains the User ID that create this record.',
  `GNTRLEX_DT_LUPD` datetime DEFAULT NULL COMMENT 'Contains the date where this record is last updated.',
  `GNTRLEX_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Contains the User ID that last update this record.',
  PRIMARY KEY (`GNTRLEX_APPS_CODE`,`GNTRLEX_ROLE_ID`,`GNTRLEX_PERM_ID`),
  KEY `FK_T_GRNTRLE_PERMEX` (`GNTRLEX_PERM_ID`),
  CONSTRAINT `FK_T_GRNTRLE_PERMEX` FOREIGN KEY (`GNTRLEX_PERM_ID`) REFERENCES `T_CORE_PERM_EX` (`PERM_ID`),
  CONSTRAINT `FK_T_GRNTRLE_ROLE` FOREIGN KEY (`GNTRLEX_APPS_CODE`, `GNTRLEX_ROLE_ID`) REFERENCES `T_CORE_ROLE` (`ROLE_APPSCODE`, `ROLE_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
