--
-- Table structure for table `T_CORE_PERM`
--

DROP TABLE IF EXISTS `T_CORE_PERM`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_PERM` (
  `PERM_ID` varchar(35) NOT NULL COMMENT 'Contains the unique ID for each permission created for the supported URI. . This shall contain the fine-grained permission that needs to be tied to a programmatic control within the URI.\nThere should always be one record for FULL access - CNSWP:MSGLIST:FULL\n <T_CORE_URI.URI_ID>:<0-10 char representation of fine-grain control>.\nEg. CNSWP:MSGLIST:DELETE',
  `PERM_URI_ID` varchar(35) NOT NULL COMMENT 'The parent URI for this record',
  `PERM_TYPE` char(1) NOT NULL COMMENT 'Type of permission, F – Full access (D), P - Programmatic Controlled Permission',
  `PERM_NAME` varchar(256) DEFAULT NULL COMMENT 'User-friendly name for this permission. ',
  `PERM_DESC` varchar(1024) DEFAULT NULL,
  `PERM_STATUS` char(1) NOT NULL COMMENT 'A is active,I is inactive,Default is A',
  `PERM_DT_ACTIVE` datetime NOT NULL COMMENT 'Specifies the date where the permission is activated,If not null, will specify the date where the application will be activated.Defaulted to CURR_DATE',
  `PERM_DT_DEACTIVE` datetime DEFAULT NULL COMMENT 'Specifies the date where the permission is de-activated,If not null, will specify the date where the application will be de-activated.  APPS_STATUS will be set to ‘I’ upon deactivated. If null, indicates that the application will not be de-activated.',
  `PERM_DT_CREATE` datetime NOT NULL COMMENT 'Default to CURR_DATE',
  `PERM_UID_CREATE` varchar(35) NOT NULL,
  `PERM_DT_LUPD` datetime DEFAULT NULL,
  `PERM_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`PERM_ID`),
  KEY `FKY__T_CORE_URI__URIID` (`PERM_URI_ID`),
  KEY `FKY__T_CORE_PERM__MPERMT_ID_idx` (`PERM_TYPE`),
  CONSTRAINT `FKY__T_CORE_PERM__MPERMT_ID` FOREIGN KEY (`PERM_TYPE`) REFERENCES `T_MST_PERM_TYPE` (`MPERMT_ID`),
  CONSTRAINT `FKY__T_CORE_URI__URIID` FOREIGN KEY (`PERM_URI_ID`) REFERENCES `T_CORE_URI` (`URI_ID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

