--
-- Table structure for table `T_CORE_SCHEDULER`
--

DROP TABLE IF EXISTS `T_CORE_SCHEDULER`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_SCHEDULER` (
  `SDLR_JOB_BEAN_ID` varchar(1024) NOT NULL COMMENT 'bean id extend iJob interface which has a doJob()',
  `SDLR_JOB_DETAILS` varchar(1024) DEFAULT NULL COMMENT 'Job Details',
  `SDLR_APPS_CODE` varchar(80) DEFAULT NULL COMMENT 'Apps code reference to T_CORE_APPS',
  `SDLR_CRON_EXPRESSION` varchar(80) DEFAULT NULL COMMENT 'SCHEDULE',
  `SDLR_STATUS` char(1) NOT NULL COMMENT 'A-Active, I-Inactive',
  `SDLR_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'Created By User',
  `SDLR_DT_CREATE` datetime DEFAULT NULL COMMENT 'Created Date',
  `SDLR_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Update by User',
  `SDLR_DT_LUPD` datetime DEFAULT NULL COMMENT 'Update Date',
  PRIMARY KEY (`SDLR_JOB_BEAN_ID`),
  KEY `FKY_T_CORE_SCHEDULER_APPS_CODE` (`SDLR_APPS_CODE`),
  CONSTRAINT `FKY_T_CORE_SCHEDULER_APPS_CODE` FOREIGN KEY (`SDLR_APPS_CODE`) REFERENCES `T_CORE_APPS` (`APPS_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='JOB Sheduler';
/*!40101 SET character_set_client = @saved_cs_client */;

