DROP TABLE IF EXISTS `T_MST_PORT_TYPE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_MST_PORT_TYPE` (
  `PORTT_CODE` varchar(35) NOT NULL COMMENT 'Port Type Code, Example: PORTT_AIR, PORTT_SEA, PORTT_LAND',
  `PORTT_DESCRIPTION` varchar(255) DEFAULT NULL COMMENT 'Description of Port Type in English',
  `PORTT_DESCRIPTION_OTH` varchar(512) DEFAULT NULL COMMENT 'Description of Port Type in other language',
  `PORTT_STATUS` char(1) NOT NULL COMMENT 'I - Inactive, A - Active',
  `PORTT_DT_CREATE` datetime DEFAULT NULL COMMENT 'Record creation datetime',
  `PORTT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'Record created userid',
  `PORTT_DT_LUPD` datetime DEFAULT NULL COMMENT 'Record update datetime',
  `PORTT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Record update userid',
  PRIMARY KEY (`PORTT_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='Master table for Port Type';
/*!40101 SET character_set_client = @saved_cs_client */;

