  `REG_CTRY_CD` varchar(2) NOT NULL COMMENT 'ISO Country Code, Linked to T_MST_COUNTRY table',
  `REG_NAME` varchar(255) DEFAULT NULL COMMENT 'ISO Country Region Name',
